  "news_id": "N:doc-10",
  "company_id": "U_19717",
  "headline": "Тарифы автоперевозок +12% бьют по логистике топлива и по вашим клиентам-перевозчикам",
  "impact_type": "mixed",
  "importance": "medium",
  "confidence": "medium",
  "what_happened": [
    {"text": "Стоимость грузовых автоперевозок по России выросла на 12% с начала года из-за дефицита водителей и подорожания дизтоплива.", "origin": "fact", "source_ids": ["N:doc-10"]},
    {"text": "Логисты и интернет-магазины пересматривают тарифы доставки до пунктов выдачи заказов.", "origin": "fact", "source_ids": ["N:doc-10"]}
  ],
  "why_it_matters": [
    {"text": "Ваше ключевое сырьё — бензин и дизельное топливо, а рост тарифов перевозок частично вызван удорожанием дизтоплива: подорожало и само топливо, и его доставка от нефтеперерабатывающих заводов и нефтебаз до ваших объектов.", "origin": "ai", "source_ids": ["F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "N:doc-10"]},
    {"text": "Среди ваших покупателей есть деятельность автомобильного грузового транспорта и ремонт автотранспорта — для них рост тарифов одновременно повышает выручку (перевозчики перекладывают издержки в цены) и издержки на топливо, что может менять объёмы закупок у вас.", "origin": "ai", "source_ids": ["P:U_9000008", "P:U_9000025", "N:doc-10"]},
    {"text": "Основной вид деятельности — розничная торговля моторным топливом: рост цен на дизтопливо увеличивает закупочную стоимость товара от поставщиков-производителей нефтепродуктов и оптовых торговцев топливом.", "origin": "ai", "source_ids": ["F:MAINOKVED_NAME", "P:U_9000006", "P:U_9000007", "N:doc-10"]}
  ],
  "consequences": [
    {"text": "Рост цен на дизтопливо повышает закупочные цены у поставщиков топлива и стоимость доставки до ваших АЗС — при фиксированной розничной марже это сжимает рентабельность, если повышение цен на колонках отстаёт от закупа.", "kind": "risk", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["F:RAW_MATERIALS", "P:U_9000006", "P:U_9000007", "N:doc-10"]},
    {"text": "Клиенты-грузоперевозчики получают рост выручки от повышения тарифов на 12%, но их издержки на топливо тоже растут; возможен сдвиг спроса на более экономичные виды топлива и пересмотр графиков закупок.", "kind": "factor", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["P:U_9000008", "N:doc-10"]},
    {"text": "Дефицит водителей в транспортной отрасли может осложнить организацию доставки топлива от нефтебаз — риск сбоев в графике поставок и необходимости держать больший запас.", "kind": "risk", "level": "low", "horizon": "medium", "origin": "ai", "source_ids": ["F:KEY_SUPPLIERS", "N:doc-10"]}
  ],
  "actions": [
    {"text": "Пересчитать экономику доставки топлива от нефтеперерабатывающих заводов и нефтебаз: сравнить рост транспортной составляющей с динамикой закупочных цен и при необходимости пересмотреть розничные цены.", "type": "action", "bank_product": null, "source_ids": ["F:KEY_SUPPLIERS", "N:doc-10"]},
    {"text": "Проверить условия договоров с поставщиками топлива: включена ли доставка в цену, есть ли индексация на транспортные тарифы, и рассмотреть фиксацию цен на горизонт 3–6 месяцев.", "type": "question", "bank_product": null, "source_ids": ["P:U_9000006", "P:U_9000007", "N:doc-10"]},
    {"text": "Если рост тарифов и цен на дизтопливо сохранится до конца года, оценить потребность в оборотном финансировании под подорожавший товарный запас — у компании уже есть кредитные продукты и факторинг, можно пересмотреть лимиты.", "type": "scenario", "bank_product": "факторинг", "source_ids": ["F:CL_PRODUCT_LOA_MARK", "F:FACTORING_MARK", "N:doc-10"]}
  ],
  "bank_view": [
    {"text": "Аналитики Альфа-Банка существенно пересмотрели вверх ожидания роста товарного импорта (на 11% г/г, прогноз $340 млрд), что говорит о восстановлении доли импорта к ВВП — это поддерживает грузопотоки и спрос на перевозки, подпитывая дефицит транспортных мощностей.", "origin": "bank", "source_ids": ["A:BA-16:0"]},
    {"text": "По прогнозу Альфа-Банка на 2026 год, дополнительные доходы экспортеров могут не реализоваться из-за логистики и санкционных рисков — логистические издержки остаются значимым ограничителем, что согласуется с ростом тарифов на перевозки.", "origin": "bank", "source_ids": ["A:BA-17:0"]}
  ],
  "company_features_used": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "F:KEY_CLIENTS", "F:CL_PRODUCT_LOA_MARK", "F:FACTORING_MARK", "P:U_9000006", "P:U_9000007", "P:U_9000008", "P:U_9000025"],
  "data_gaps": ["Нет данных о доле транспортных расходов в себестоимости компании", "Нет данных о структуре поставок (самовывоз vs доставка поставщиком)", "Нет аналитики Альфа-Банка непосредственно по рынку автоперевозок и ценам на дизтопливо"]
}
